package dev.sablelife.testing;
import dev.sablelife.module.*;
import net.minecraft.core.Direction;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_summon_tests") @PrefixGameTestTemplate(false)
public final class SummonConfigurationGameTests {
 @GameTest(template="combat",batch="summon_area") public static void DisabledTemplateStillProducesReferencedImpactAreaWhileSummonRuns(GameTestHelper h){var c=SlashGuardGameTests.core(h);var area=c.modules().add("surface_field");var a=c.modules().add("gun");a.edit("enabled",0,"");a.impactField(area.id());var m=c.modules().add("summoned_weapon");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.DOWN)));m.projectileItem(new ItemStack(Items.CROSSBOW),h.getLevel().registryAccess());m.summonAttack(a.id());m.edit("startDistance",3,"");var point=ModuleSummonedWeapon.position(c,m);var floor=net.minecraft.core.BlockPos.containing(point.add(0,-2,0));for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)h.getLevel().setBlockAndUpdate(floor.offset(x,0,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);var shots=h.getLevel().getEntitiesOfClass(dev.sablelife.attack.ModuleShot.class,new AABB(point,point).inflate(10)).stream().filter(e->e.getPersistentData().hasUUID("SableLifeAttackOwner")&&e.getPersistentData().getUUID("SableLifeAttackOwner").equals(c.creatureId())).toList();h.assertTrue(shots.size()==1,"Expected one summoned shot");shots.getFirst().tick();h.assertTrue(c.modules().surfaceFields.count()==1,"Disabled template lost referenced impact area");c.modules().summonedWeapons.clear();c.modules().surfaceFields.tick(c);h.assertTrue(c.modules().surfaceFields.count()==0,"Disabled source area remained active without its summon");h.succeed();}
 private static final class Author extends net.neoforged.neoforge.common.util.FakePlayer {private int next;Author(net.minecraft.server.level.ServerLevel l){super(l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"SummonAuthor"));setGameMode(net.minecraft.world.level.GameType.CREATIVE);}@Override public java.util.OptionalInt openMenu(net.minecraft.world.MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> extra){closeContainer();containerMenu=provider.createMenu(++next,getInventory(),this);return java.util.OptionalInt.of(next);}}
 @GameTest(template="combat") public static void SourceSelectorValidatesTypesAndItemMenuIsDisplayOnly(GameTestHelper h){var c=SlashGuardGameTests.core(h);var source=c.modules().add("gun");c.modules().add("sound");var m=c.modules().add("summoned_weapon");var p=new Author(h.getLevel());p.setPos(ModuleArena.corePosition(c));var menu=new HeartDashboardMenu(1,p.getInventory(),c);h.assertTrue(!menu.action(p,c.modules().revision(),m.id(),"edit","summonAttack",2,"")&&!menu.action(p,c.modules().revision(),m.id(),"edit","summonAttack",999,""),"Invalid template accepted");h.assertTrue(menu.action(p,c.modules().revision(),m.id(),"edit","summonAttack",1,"")&&m.summonAttackId().equals(source.id()),"Gun selector did not bind UUID");h.assertTrue(menu.action(p,c.modules().revision(),m.id(),"projectile","",0,"")&&p.containerMenu instanceof ProjectileItemMenu item&&item.displayOnly(),"Summon item picker was not display-only");h.assertTrue(c.modules().copy(m.id()).summonAttackId().equals(source.id())&&VirtualModule.load(m.save()).summonAttackId().equals(source.id())&&ModulePreset.create(m.save()).summonAttackId()==null,"Copy/save/preset binding semantics wrong");h.succeed();}
 @GameTest(template="combat") public static void TrackingUsesSummonCategoryAimOffsetAndRotatedMuzzle(GameTestHelper h){var c=SlashGuardGameTests.core(h);var a=c.modules().add("gun");a.edit("enabled",0,"");a.edit("shotAim",1,"");a.edit("target",0,"");a.edit("startDistance",32,"");var m=c.modules().add("summoned_weapon");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.EAST)));m.projectileItem(new ItemStack(Items.CROSSBOW),h.getLevel().registryAccess());m.summonAttack(a.id());m.edit("startDistance",3,"");m.edit("summonAim",1,"");m.edit("target",1,"");m.edit("targetRange",8,"");m.edit("summonTurnSpeed",180,"");m.edit("summonYaw",30,"");m.edit("summonMuzzleZ",2,"");var point=ModuleSummonedWeapon.position(c,m);var cow=net.minecraft.world.entity.EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(point.add(0,-cow.getBbHeight()/2,6));h.getLevel().addFreshEntity(cow);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);var f=c.modules().summonedWeapons.frame(m.id());var expected=new Vec3(.5,0,Math.sqrt(3)/2);h.assertTrue(f!=null&&f.direction().distanceToSqr(expected)<1e-8&&f.muzzle().distanceToSqr(point.add(expected.scale(2)))<1e-8,"Tracking category, yaw offset or local muzzle was ignored");var shots=h.getLevel().getEntitiesOfClass(dev.sablelife.attack.ModuleShot.class,new AABB(point,point).inflate(12)).stream().filter(e->e.getPersistentData().hasUUID("SableLifeAttackOwner")&&e.getPersistentData().getUUID("SableLifeAttackOwner").equals(c.creatureId())).toList();h.assertTrue(shots.size()==1&&shots.getFirst().getDeltaMovement().normalize().distanceToSqr(expected)<1e-8,"Gun reused its own target aim instead of summon orientation");shots.forEach(net.minecraft.world.entity.Entity::discard);cow.discard();c.modules().summonedWeapons.clear();h.succeed();}
 @GameTest(template="combat",batch="summon_lifecycle_editors") public static void LifecycleParticleEditorsOpenAndAllElevenTemplatesBind(GameTestHelper h){var c=SlashGuardGameTests.core(h);var m=c.modules().add("summoned_weapon");var player=new Author(h.getLevel());player.setPos(ModuleArena.corePosition(c));for(String key:List.of("summonSpawnParticles","summonEndParticles")){var menu=new HeartDashboardMenu(1,player.getInventory(),c);h.assertTrue(menu.action(player,c.modules().revision(),m.id(),"effects",key,0,"")&&player.containerMenu instanceof EffectSelectionMenu,"Particle editor did not open: "+key);}
  for(String type:ModuleSummonedWeapon.ATTACKS){var a=c.modules().add(type);var menu=new HeartDashboardMenu(1,player.getInventory(),c);h.assertTrue(menu.action(player,c.modules().revision(),m.id(),"edit","summonAttack",c.modules().all().indexOf(a)+1,"")&&m.summonAttackId().equals(a.id()),"Template selection rejected "+type);}
  h.assertTrue(ModulePreset.create(m.save()).projectileItem(h.getLevel().registryAccess()).is(Items.DISPENSER),"Portable preset lost default display item");h.succeed();}

}
